const RoomCard: React.FC<{ room: Room }> = ({ room }) => {
  const [currentImage, setCurrentImage] = useState(0);

  const nextImage = (e: React.MouseEvent) => {
    e.preventDefault();
    setCurrentImage((prev) => (prev + 1) % room.images.length);
  };

  const prevImage = (e: React.MouseEvent) => {
    e.preventDefault();
    setCurrentImage((prev) => (prev - 1 + room.images.length) % room.images.length);
  };

  return (
    <motion.div 
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.5 }}
      className="bg-white rounded-2xl overflow-hidden shadow-lg hover:shadow-2xl transition-all duration-300 group"
    >
      {/* Image Carousel */}
      <div className="relative h-64 overflow-hidden">
        <motion.img
          key={currentImage}
          src={room.images[currentImage]}
          alt={room.name}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.5 }}
          className="w-full h-full object-cover transform group-hover:scale-110 transition-transform duration-700"
        />

        <div className="absolute inset-0 bg-black/20 group-hover:bg-black/10 transition-colors"></div>

        <button 
          onClick={prevImage}
          className="absolute left-2 top-1/2 -translate-y-1/2 bg-white/80 p-1 rounded-full hover:bg-white text-resort-green opacity-0 group-hover:opacity-100 transition-opacity"
        >
          <ChevronLeft size={20} />
        </button>
        <button 
          onClick={nextImage}
          className="absolute right-2 top-1/2 -translate-y-1/2 bg-white/80 p-1 rounded-full hover:bg-white text-resort-green opacity-0 group-hover:opacity-100 transition-opacity"
        >
          <ChevronRight size={20} />
        </button>

        <div className="absolute bottom-4 left-0 right-0 flex justify-center gap-2">
            {room.images.map((_, idx) => (
                <div key={idx} className={`h-1.5 w-1.5 rounded-full ${idx === currentImage ? 'bg-white' : 'bg-white/50'}`} />
            ))}
        </div>
      </div>

      {/* Content */}
      <div className="p-8">
        <div className="flex justify-between items-start mb-4">
          <h3 className="text-2xl font-serif font-bold text-resort-green">{room.name}</h3>
          <div className="text-right">
            <span className="block text-resort-gold font-bold text-xl">GH₵ {room.price}</span>
            <span className="text-xs text-stone-400 uppercase tracking-wide">Per Night</span>
          </div>
        </div>

        <p className="text-stone-600 mb-6 text-sm leading-relaxed min-h-[3rem]">
          {room.description}
        </p>

        {/* Features Icons */}
        <div className="flex flex-wrap gap-4 mb-8 text-stone-500 text-xs uppercase tracking-wide font-medium">
            {room.features.slice(0,3).map((feat, i) => (
                <div key={i} className="flex items-center gap-1 bg-stone-100 px-2 py-1 rounded">
                    {i === 0 && <Users size={14} />}
                    {i === 1 && <Maximize size={14} />}
                    {i === 2 && feat.includes('View') ? <Maximize size={14}/> : feat.includes('WiFi') ? <Wifi size={14}/> : <div className="w-3 h-3 bg-resort-gold rounded-full"/>}
                    {feat}
                </div>
            ))}
        </div>

        <a 
            href="#booking"
            className="block w-full text-center bg-resort-green text-white py-3 rounded-sm font-bold uppercase text-sm tracking-widest hover:bg-resort-brown transition-colors"
        >
          Book This Room
