import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';

export const Booking: React.FC = () => {
  const [formData, setFormData] = useState({
    checkIn: '',
    checkOut: '',
    guests: 2,
    roomType: 'deluxe-lake'
  });

  const [estimatedPrice, setEstimatedPrice] = useState(0);

  const roomPrices: {[key: string]: number} = {
    'deluxe-lake': 1500,
    'forest-suite': 2200,
    'royal-villa': 4500
  };

  useEffect(() => {
    const start = new Date(formData.checkIn);
    const end = new Date(formData.checkOut);
    const pricePerNight = roomPrices[formData.roomType];

    if (start && end && !isNaN(start.getTime()) && !isNaN(end.getTime()) && end > start) {
      const diffTime = Math.abs(end.getTime() - start.getTime());
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      setEstimatedPrice(diffDays * pricePerNight);
    } else {
      setEstimatedPrice(0);
    }
  }, [formData]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    alert("Booking request simulated! In a real app, this would send data to a backend.");
  };

  return (
    <div className="py-20 bg-stone-100">
      <div className="container mx-auto px-6">
        <div className="bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col md:flex-row">

          {/* Image Side */}
          <div className="md:w-5/12 relative min-h-[300px] md:min-h-full">
            <img 
              src="https://picsum.photos/800/1200?random=99" 
              alt="Booking" 
