const App: React.FC = () => {
  const [activeSection, setActiveSection] = useState('home');

  // Simple intersection observer to update active state for navbar
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setActiveSection(entry.target.id);
          }
        });
      },
      { threshold: 0.5 }
    );

    document.querySelectorAll('section').forEach((section) => {
      observer.observe(section);
    });

    return () => observer.disconnect();
  }, []);

  return (
    <div className="h-screen w-full overflow-y-scroll snap-y snap-mandatory scroll-smooth bg-black text-white no-scrollbar">
      <Navbar activeSection={activeSection} />

      <section id="home" className="h-screen w-full snap-start relative">
        <Hero />
      </section>

      <section id="about" className="h-screen w-full snap-start relative">
        <About />
      </section>

      <section id="rooms" className="h-screen w-full snap-start relative">
        <Rooms />
      </section>

      <section id="amenities" className="h-screen w-full snap-start relative">
        <Amenities />
      </section>

      <section id="gallery" className="h-screen w-full snap-start relative">
        <Gallery />
      </section>

      <section id="booking" className="h-screen w-full snap-start relative">
        <Booking />
      </section>

      <section id="contact" className="h-screen w-full snap-start relative">
        <Contact />
      </section>
    </div>
  );
};

