import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { About } from './components/About';
import { Rooms } from './components/Rooms';
import { Amenities } from './components/Amenities';
import { Gallery } from './components/Gallery';
import { Booking } from './components/Booking';
import { Contact } from './components/Contact';

const App: React.FC = () => {
  const [activeSection, setActiveSection] = useState('home');
  const [selectedRoom, setSelectedRoom] = useState('');

  // Function to handle booking from Room cards
  const handleBookRoom = (roomId: string) => {
    setSelectedRoom(roomId);
    const bookingSection = document.getElementById('booking');
    if (bookingSection) {
      bookingSection.scrollIntoView({ behavior: 'smooth' });
    }
  };

  // Simple intersection observer to update active state for navbar
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setActiveSection(entry.target.id);
          }
        });
      },
      { threshold: 0.5 }
    );

    document.querySelectorAll('section').forEach((section) => {
      observer.observe(section);
    });

    return () => observer.disconnect();
  }, []);

  return (
    <div className="h-screen w-full overflow-y-scroll snap-y snap-mandatory scroll-smooth bg-black text-white no-scrollbar">
      <Navbar activeSection={activeSection} />

      <section id="home" className="h-screen w-full snap-start relative">
        <Hero />
      </section>

      <section id="about" className="h-screen w-full snap-start relative">
        <About />
      </section>

      <section id="rooms" className="h-screen w-full snap-start relative">
        <Rooms onBook={handleBookRoom} />
      </section>

      <section id="amenities" className="h-screen w-full snap-start relative">
        <Amenities />
      </section>

      <section id="gallery" className="h-screen w-full snap-start relative">
        <Gallery />
      </section>

      <section id="booking" className="h-screen w-full snap-start relative">
        <Booking preselectedRoom={selectedRoom} />
      </section>

      <section id="contact" className="h-screen w-full snap-start relative">
        <Contact />
      </section>
    </div>
  );
};

