/* Smooth scrolling for the whole page */
html {
    scroll-behavior: smooth;
}

/* Hide scrollbar for Chrome, Safari and Opera */
.no-scrollbar::-webkit-scrollbar {
    display: none;
}

/* Hide scrollbar for IE, Edge and Firefox */
.no-scrollbar {
    -ms-overflow-style: none;  /* IE and Edge */
    scrollbar-width: none;  /* Firefox */
}

/* Reveal Animations */
.reveal {
    opacity: 0;
    transform: translateY(30px);
    transition: all 0.8s ease-out;
}

.reveal.active {
    opacity: 1;
    transform: translateY(0);
}

.reveal.slide-right {
    transform: translateX(-50px) rotate(-2deg);
}

.reveal.slide-right.active {
    transform: translateX(0) rotate(0);
}

.reveal.slide-up {
    transform: translateY(50px);
}

.reveal.slide-up.active {
    transform: translateY(0);
}

/* Fade in specific helper */
.fade-in {
    animation: fadeIn 0.5s ease-in-out forwards;
}

@keyframes fadeIn {
    from { opacity: 0; transform: scale(0.95); }
    to { opacity: 1; transform: scale(1); }
}

/* Nav Link Hover Underline effect */
.nav-link {
    position: relative;
}

/* Navbar Scrolled State */
.navbar-scrolled {
    background-color: rgba(12, 10, 9, 0.8); /* stone-900 with opacity */
    backdrop-filter: blur(12px);
    padding-top: 1rem !important; /* py-4 */
    padding-bottom: 1rem !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

/* Hide Navbar items on scroll for cleaner look, or style them differently? 
   Let's just scale the logo slightly down */
.navbar-scrolled .nav-item {
    transform: scale(0.95);
}

/* Lightbox Animation */
#lightbox-img {
    transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

